import { Check, Copy } from 'lucide-react'
import { useState } from 'react'

import { cx } from '~/lib/cx'
import styles from './code-block.module.scss'

export interface CodeBlockProps {
  code: string
  language?: string
  title?: string
  copyable?: boolean
  className?: string
}

/** Read-only code block with an optional copy affordance. */
export function CodeBlock({
  code,
  language,
  title,
  copyable = true,
  className,
}: CodeBlockProps) {
  const [copied, setCopied] = useState(false)

  async function copy() {
    try {
      await navigator.clipboard.writeText(code)
      setCopied(true)
      window.setTimeout(() => setCopied(false), 1500)
    } catch {
      setCopied(false)
    }
  }

  return (
    <figure className={cx(styles.root, className)}>
      {title || language || copyable ? (
        <figcaption className={styles.header}>
          <span className={styles.title}>{title ?? language ?? 'Code'}</span>
          {copyable ? (
            <button
              type="button"
              className={styles.copy}
              onClick={copy}
              aria-label={copied ? 'Copied' : 'Copy code'}
            >
              {copied ? <Check aria-hidden /> : <Copy aria-hidden />}
            </button>
          ) : null}
        </figcaption>
      ) : null}
      <pre className={styles.pre}>
        <code className={styles.code}>{code}</code>
      </pre>
    </figure>
  )
}

@use '../../styles' as vz;

.root {
  overflow: hidden;
  border: 1px solid vz.color('border');
  border-radius: vz.radius('lg');
  background: vz.color('code-bg');
  color: vz.color('code-fg');
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: vz.space(3);
  padding: vz.space(2) vz.space(3);
  border-bottom: 1px solid vz.color('code-border');
}

.title {
  color: vz.color('code-muted');
  font-size: vz.font-size('xs');
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.copy {
  display: inline-flex;
  padding: vz.space(1);
  border-radius: vz.radius('sm');
  color: vz.color('code-muted');

  &:hover {
    background: vz.color('code-border');
    color: vz.color('code-fg');
  }

  svg {
    width: 16px;
    height: 16px;
  }
}

.pre {
  margin: 0;
  padding: vz.space(4);
  overflow: auto;
  font-size: vz.font-size('sm');
  line-height: 1.6;
}

.code {
  font-family: SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  white-space: pre;
}
